import java.io.IOException;
import java.io.InputStream;

interface PayloadReader {
    /**
     * Reads the remaining bytes.
     * Ownership stays with the caller; this method must not close input on success or read failure.
     */
    byte[] read(InputStream input) throws IOException;
}

import java.io.IOException;
import java.io.InputStream;

final class StreamPayloadReader implements PayloadReader {
    @Override
    public byte[] read(InputStream input) throws IOException {
        try (input) {
            return input.readAllBytes();
        }
    }
}

